const item = $input.first().json;

// Retrieve raw HTML from the upstream Check HTTP Error node
const rawHtml = item.data || '';

function cleanHtmlToText(html) {
  if (!html || typeof html !== 'string') return '';
  return html
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, ' ')
    .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, ' ')
    .replace(/<svg\b[^<]*(?:(?!<\/svg>)<[^<]*)*<\/svg>/gi, ' ')
    .replace(/<noscript\b[^<]*(?:(?!<\/noscript>)<[^<]*)*<\/noscript>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 12000); // Truncate to avoid context window overflow
}

const plainText = cleanHtmlToText(rawHtml);

// Resolve domain and canonical URL using valid JavaScript OR (||)
// Resolve plain text from whatever input fed this node
const domain = item.domain || item.candidate_domain || '';
const url = item.candidate_url || item.url || (domain ? `https://${domain}` : '');

return [{
  json: {
    domain: domain,
    url: url,
    website_text: plainText
  }
}];

// Input arrives from the Research Request webhook (validated upstream)
const rawInput = $('Validate Request').first().json.input.trim();

// Domain detection regex / check
const isDomain = /^([a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}(\/.*)?$/.test(rawInput) || rawInput.startsWith('http');

if (isDomain) {
  let cleanDomain = rawInput.replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('/')[0].toLowerCase();
  return {
    json: {
      input_type: 'domain',
      raw_input: rawInput,
      candidate_domain: cleanDomain,
      candidate_url: `https://${cleanDomain}`
    }
  };
} else {
  return {
    json: {
      input_type: 'name',
      raw_input: rawInput,
      company_name: rawInput
    }
  };
}

const items = $input.all();
const query = $('Normalize Input').first().json.company_name?.toLowerCase().trim() || '';

// High-profile non-company domains to reject
const ignoredDomains = [
  'linkedin.com', 'twitter.com', 'x.com', 'facebook.com', 'instagram.com',
  'crunchbase.com', 'bloomberg.com', 'wikipedia.org', 'pitchbook.com',
  'glassdoor.com', 'indeed.com', 'youtube.com', 'zoominfo.com'
];

// Hostname without "www." (regex, so it does not depend on the URL global)
function extractDomain(inputUrl) {
  const match = String(inputUrl || '').trim().match(/^(?:https?:\/\/)?([^\/?#:\s]+)/i);
  return match ? match[1].toLowerCase().replace(/^www\./, '') : '';
}

const candidates = [];

for (const item of items) {
  const url = item.json.url || '';
  const title = (item.json.title || '').toLowerCase();
  const hostname = /^https?:\/\//i.test(url) ? extractDomain(url) : '';
  if (!hostname) continue;

  // Filter out social, directory, and media platforms
  if (ignoredDomains.some(d => hostname === d || hostname.endsWith('.' + d))) continue;

  let score = 0;
  const cleanName = query.replace(/[^a-z0-9]/g, '');
  const cleanHost = hostname.split('.')[0].replace(/[^a-z0-9]/g, '');

  if (cleanHost === cleanName) score += 50;
  else if (cleanHost.includes(cleanName) || cleanName.includes(cleanHost)) score += 30;
  if (title.includes(query)) score += 25;

  candidates.push({
    domain: hostname,
    url: url,
    title: item.json.title,
    score: score
  });
}

candidates.sort((a, b) => b.score - a.score);

// Fallback to the top candidate directly without a hard cutoff
if (candidates.length > 0 && (candidates[0].domain || candidates[0].url)) {
  const topMatch = candidates[0];
  const domain = extractDomain(topMatch.domain || topMatch.url);
  return [{
    json: {
      status: 'resolved',
      candidate_domain: domain,
      candidate_url: topMatch.url?.startsWith('http') ? topMatch.url : `https://${domain}`,
      confidence: topMatch.score || 0
    }
  }];
}

// No usable website among the search results
return [{
  json: {
    status: 'not_found',
    candidate_domain: '',
    candidate_url: '',
    confidence: 0
  }
}];

