={{ (() => {
  let name = '';
  try {
    const raw = $json.output?.[0]?.content?.[0]?.text || '';
    const parsed = JSON.parse(raw.replace(/```json\n?|```/g, '').trim());
    name = parsed.company_name;
  } catch(e) {}

  const target = name 
    || $('Rank Website Candidates').first()?.json?.candidate_domain 
    || $('Is Domain Input?').first()?.json?.company_name 
    || $('Normalize Input').first()?.json?.candidate_domain;

  return `"${target}" news expansion acquisition hiring technology`;
})() }}

value.company_facts:
={{ 
  (() => {
    const nodeData = $('Extract Core Company Facts').first()?.json;
    const rawText = nodeData?.output?.[0]?.content?.[0]?.text || '';
    const cleaned = rawText.replace(/```json\n?|```/g, '').trim();
    try { 
      return JSON.parse(cleaned); 
    } catch (e) { 
      return { raw: rawText }; 
    } 
  })() 
}}

